67	// checkpoints, trails not enabled) records a one-line skip note instead of
68	// failing the command.
69	func gatherTuningContext(ctx context.Context, errW io.Writer, repoRoot string, src tuneSources, limit int) string {
70		var b strings.Builder
71	
72		if src.repo {
73			b.WriteString("### Repository (static)\n\n")
74			b.WriteString(gatherRepoStatics(repoRoot))
75			b.WriteString("\n")
76		}
