	repoRoot := t.TempDir()
	dir := filepath.Join(repoRoot, ".entire", "runners")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "trail-risk.json"),
		[]byte(`{"id":"trail-risk","prompt":{"template":"x"}}`), 0o644); err != nil {
